import os
import sys


def normalize(line):
    if line.count("@") != 1:
        return None
    local, domain = line.split("@")
    if not domain or "." not in domain:
        return None
    if domain.startswith(".") or domain.endswith("."):
        return None
    if domain == "gmail.com":
        local = local.split("+", 1)[0].replace(".", "")
    if not local:
        return None
    return local + "@" + domain


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "emails.txt")
    valid = set()
    invalid = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for raw in f:
            line = raw.strip().lower()
            if not line:
                continue
            addr = normalize(line)
            if addr is None:
                invalid += 1
            else:
                valid.add(addr)
    out = sys.stdout
    for a in sorted(valid, key=lambda s: s.encode("utf-8")):
        out.write(a + "\n")
    out.write(f"invalid {invalid}\n")


if __name__ == "__main__":
    main()

import os
import re

VALUES = [
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
]

ROMAN_DIGITS = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}


def to_roman(n):
    out = []
    for v, s in VALUES:
        while n >= v:
            out.append(s)
            n -= v
    return ''.join(out)


def from_roman(s):
    total = 0
    for i, ch in enumerate(s):
        v = ROMAN_DIGITS[ch]
        if i + 1 < len(s) and ROMAN_DIGITS[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total


def convert(value):
    if re.fullmatch(r'[0-9]+', value):
        n = int(value)
        if 1 <= n <= 3999:
            return to_roman(n)
        return None
    if re.fullmatch(r'[IVXLCDM]+', value):
        n = from_roman(value)
        if 1 <= n <= 3999 and to_roman(n) == value:
            return str(n)
    return None


def main():
    input_dir = os.environ['INPUT']
    path = os.path.join(input_dir, 'numbers.txt')
    with open(path, encoding='utf-8') as f:
        for line in f:
            value = line.strip()
            if not value:
                continue
            result = convert(value)
            print(f"{value} = {result if result is not None else 'invalid'}")


if __name__ == '__main__':
    main()

import os


PAIRS = {')': '(', ']': '[', '}': '{'}
CLOSER_FOR = {'(': ')', '[': ']', '{': '}'}


def check_line(line):
    stack = []
    for col, ch in enumerate(line, 1):
        if ch in CLOSER_FOR:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack:
                return f"col {col}: unexpected {ch}"
            top = stack.pop()
            if top != PAIRS[ch]:
                return f"col {col}: expected {CLOSER_FOR[top]}, found {ch}"
    if stack:
        return f"unclosed {CLOSER_FOR[stack[-1]]}"
    return "ok"


def main():
    input_dir = os.environ["INPUT"]
    path = os.path.join(input_dir, "snippets.txt")
    with open(path, "r", encoding="utf-8", newline="") as f:
        data = f.read()

    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    lines = [line.rstrip("\r") for line in lines]

    for line in lines:
        print(check_line(line))


