    main()

import heapq
import os


def dists_to(target, adj):
    """Shortest distance from every reachable town to `target` (Dijkstra)."""
    dist = {target: 0}
    pq = [(0, target)]
    while pq:
        du, u = heapq.heappop(pq)
        if du > dist[u]:
            continue
        for v, w in adj.get(u, {}).items():
            nd = du + w
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "routes.txt")

    adj = {}
    trips = []

    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) >= 4:
                a, b, c = parts[1], parts[2], int(parts[3])
                for x, y in ((a, b), (b, a)):
                    cur = adj.setdefault(x, {})
                    if y not in cur or c < cur[y]:
                        cur[y] = c
            elif parts[0] == "trip" and len(parts) >= 3:
                trips.append((parts[1], parts[2]))

    cache = {}
    out = []
    for s, t in trips:
        if s == t:
            out.append(f"{s} 0")
            continue
        if t not in cache:
            cache[t] = dists_to(t, adj)
        d = cache[t]
        if s not in d:
            out.append(f"{s} {t} unreachable")
            continue
        # Greedy walk: at each town, take the smallest neighbour that lies
        # on some shortest path to t. This yields the lexicographically
        # smallest cheapest route (all costs are positive, so no cycles).
        route = [s]
        u = s
        while u != t:
            best = None
            for v, w in adj.get(u, {}).items():
                if v in d and w + d[v] == d[u]:
                    if best is None or v < best:
                        best = v
            u = best
            route.append(u)
        out.append(" -> ".join(route) + f" {d[s]}")

    if out:
        print("\n".join(out))


if __name__ == "__main__":
    main()

import json
import os
import sys


def merge_obj(base, override):
    result = dict(base)
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict):
            existing = result.get(key)
            if isinstance(existing, dict):
                result[key] = merge_obj(existing, value)
            else:
                result[key] = merge_obj({}, value)
        else:
            result[key] = value
    return result


def join_path(path, key):
    if path is None:
        return key
    return path + "." + key


def flatten(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path if path is not None else "", "{}"))
            return
        for key in value:
            flatten(value[key], join_path(path, key), out)
    elif isinstance(value, list):
        if not value:
            out.append((path if path is not None else "", "[]"))
            return
        for index, item in enumerate(value):
            flatten(item, join_path(path, str(index)), out)
    else:
        out.append((path if path is not None else "", json.dumps(value)))


def load_object(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def main():
    input_dir = os.environ["INPUT"]
    base = load_object(os.path.join(input_dir, "base.json"))
    override = load_object(os.path.join(input_dir, "override.json"))

    if isinstance(base, dict) and isinstance(override, dict):
        merged = merge_obj(base, override)
    else:
        merged = override if override is not None else base

    leaves = []
    flatten(merged, None, leaves)
    leaves.sort(key=lambda item: item[0].encode("utf-8"))

    out = sys.stdout
    for path, rendered in leaves:
        out.write(f"{path}={rendered}\n")
    out.flush()


if __name__ == "__main__":
    main()

import os
from pathlib import Path


def main():
    inp = Path(os.environ["INPUT"])
    out = Path(os.environ["OUT"])

    targets = {
        "ERROR": "error.log",
        "WARN": "warn.log",
        "WARNING": "warn.log",
        "INFO": "info.log",
    }
    buckets = {"error.log": [], "warn.log": [], "info.log": []}
    other = 0

    with open(inp / "app.log", encoding="utf-8", newline="") as f:
        data = f.read()

    for raw in data.split("\n"):
        line = raw[:-1] if raw.endswith("\r") else raw
        if not line.strip():
            continue
        fields = line.split()
        if len(fields) >= 3 and fields[1].upper() in targets:
            buckets[targets[fields[1].upper()]].append(line)
        else:
            other += 1

    out.mkdir(parents=True, exist_ok=True)
    for name, lines in buckets.items():
        with open(out / name, "w", encoding="utf-8", newline="\n") as g:
            for line in lines:
                g.write(line + "\n")

    print(f"error {len(buckets['error.log'])}")
    print(f"warn {len(buckets['warn.log'])}")
    print(f"info {len(buckets['info.log'])}")
    print(f"other {other}")


if __name__ == "__main__":
    main()

import json
import os


def main():
    input_dir = os.environ["INPUT"]
    counts_path = os.environ["COUNTS"]

    # Load totals from earlier runs; the file is absent on the first run.
    totals = {}
    if os.path.exists(counts_path):
        with open(counts_path, "r", encoding="utf-8") as f:
            content = f.read()
        if content.strip():
            totals = json.loads(content)

    # Count this run's visits.
    visits = {}
    with open(os.path.join(input_dir, "visits.txt"), "r", encoding="utf-8") as f:
        for line in f:
            page = line.strip()
            if page:
                visits[page] = visits.get(page, 0) + 1

    for page, n in visits.items():
        totals[page] = totals.get(page, 0) + n

    # Write state atomically so an interrupted run cannot corrupt it.
    tmp_path = counts_path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(totals, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp_path, counts_path)

    # Highest total first, then page in byte order.
    for page in sorted(totals, key=lambda p: (-totals[p], p.encode("utf-8"))):
        print(f"{page} {totals[page]}")


if __name__ == "__main__":
    main()

import json
import os


def load(path):
    if not os.path.exists(path):
        return {}
    with open(path, encoding="utf-8") as f:
        content = f.read()
    if not content.strip():
        return {}
    return json.loads(content)


def save(path, users):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(users, f)
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    users_path = os.environ["USERS"]

    users = load(users_path)

    with open(os.path.join(input_dir, "commands.txt"), encoding="utf-8") as f:
        lines = f.read().splitlines()

    out = []
    changed = False

    for raw in lines:
        line = raw.strip()
        if not line:
            continue

        parts = line.split()
        cmd = parts[0]
        n = len(parts)

        if cmd == "put" and n == 4:
            _, uid, name, email = parts
            users[uid] = {"name": name, "email": email}
            changed = True
            out.append(f"ok {uid}")

        elif cmd == "rename" and n == 3:
            uid, name = parts[1], parts[2]
            if uid in users:
                users[uid]["name"] = name
                changed = True
                out.append(f"ok {uid}")
            else:
                out.append(f"missing {uid}")

        elif cmd == "get" and n == 2:
            uid = parts[1]
            if uid in users:
                u = users[uid]
                out.append(json.dumps(
                    {"id": uid, "name": u["name"], "email": u["email"]},
                    separators=(",", ":")))
            else:
                out.append(f"missing {uid}")

        elif cmd == "del" and n == 2:
            uid = parts[1]
            if uid in users:
                del users[uid]
                changed = True
                out.append(f"ok {uid}")
            else:
                out.append(f"missing {uid}")

        elif cmd == "count" and n == 1:
            out.append(f"count {len(users)}")

        else:
            out.append(f"bad {line}")

    if changed:
        save(users_path, users)

    for line in out:
        print(line)


if __name__ == "__main__":
    main()

import json
import os
import sys


def load_state(path):
    if not os.path.exists(path) or os.path.getsize(path) == 0:
        return set(), {}
    with open(path, "rb") as f:
        st = json.loads(f.read().decode("utf-8"))
    return set(st.get("applied", [])), dict(st.get("balances", {}))


def save_state(path, applied, balances):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"applied": sorted(applied), "balances": balances}, f)
    os.replace(tmp, path)


def parse_event(raw):
    try:
        obj = json.loads(raw.decode("utf-8"))
    except (ValueError, RecursionError):
        return None
    if not isinstance(obj, dict):
        return None
    eid = obj.get("id")
    acct = obj.get("account")
    cents = obj.get("cents")
    if not isinstance(eid, str) or not isinstance(acct, str) or type(cents) is not int:
        return None
    return eid, acct, cents


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]

    applied, balances = load_state(state_path)

    try:
        with open(os.path.join(input_dir, "events.jsonl"), "rb") as f:
            data = f.read()
    except FileNotFoundError:
        data = b""

    applied_n = 0
    dup = 0
    rej = 0

    for raw in data.split(b"\n"):
        if not raw.strip():
            continue
        event = parse_event(raw)
        if event is None:
            rej += 1
            continue
        eid, acct, cents = event
        if eid in applied:
            dup += 1
            continue
        applied.add(eid)
        balances[acct] = balances.get(acct, 0) + cents
        applied_n += 1

    save_state(state_path, applied, balances)

    out = [f"applied {applied_n} duplicate {dup} rejected {rej}"]
    for acct in sorted(balances, key=lambda a: a.encode("utf-8", "surrogatepass")):
        out.append(f"{acct} {balances[acct]}")
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))


if __name__ == "__main__":
    main()

import json
import os


def load_totals(path):
    if not os.path.exists(path):
        return {}
    with open(path, encoding="utf-8") as f:
        text = f.read()
    if not text.strip():
        return {}
    data = json.loads(text)
    return {name: [int(v[0]), int(v[1])] for name, v in data.items()}


def save_totals(path, totals):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(totals, f, sort_keys=True)
    os.replace(tmp, path)


def add(totals, name, points):
    entry = totals.setdefault(name, [0, 0])
    entry[0] += points
    entry[1] += 1


def main():
    input_dir = os.environ["INPUT"]
    board_path = os.environ["BOARD"]

    totals = load_totals(board_path)

    games_path = os.path.join(input_dir, "games.txt")
    if os.path.exists(games_path):
        with open(games_path, encoding="utf-8") as f:
            for line in f:
                parts = line.split()
                if len(parts) == 2:
                    winner, loser = parts
                    add(totals, winner, 3)
                    add(totals, loser, 0)
                elif len(parts) == 3 and parts[2] == "draw":
                    a, b = parts[0], parts[1]
                    add(totals, a, 1)
                    add(totals, b, 1)

    save_totals(board_path, totals)

    ranked = sorted(
        totals.items(),
        key=lambda kv: (-kv[1][0], kv[1][1], kv[0].encode("utf-8")),
    )
    for rank, (name, (points, played)) in enumerate(ranked[:3], start=1):
        print(f"{rank}. {name} {points} {played}")


if __name__ == "__main__":
    main()

import os
import re
import sqlite3

MOVE_RE = re.compile(r"[+-][0-9]+")


def main():
    input_dir = os.environ["INPUT"]
    stock_path = os.environ["STOCK"]

    moves_path = os.path.join(input_dir, "moves.txt")
    try:
        with open(moves_path, "r", encoding="utf-8") as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    # Parse the file into batches. Malformed batches are kept but marked bad.
    batches = []
    current = None
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "batch":
            name = line[len("batch"):].strip()
            current = {"name": name, "moves": [], "ok": True}
            batches.append(current)
            continue
        if current is None:
            # A move line outside any batch has no batch to belong to.
            continue
        if len(parts) == 2 and MOVE_RE.fullmatch(parts[1]):
            delta = int(parts[1])
            if delta != 0:
                current["moves"].append((parts[0], delta))
                continue
        current["ok"] = False

    con = sqlite3.connect(stock_path, isolation_level=None)
    con.execute(
        "CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)"
    )
    con.execute("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)")

    for b in batches:
        name = b["name"]

        if con.execute("SELECT 1 FROM applied WHERE name = ?", (name,)).fetchone():
            print(f"{name} skipped")
            continue

        status = "rejected"
        if b["ok"]:
            con.execute("BEGIN IMMEDIATE")
            try:
                pending = {}
                good = True
                for sku, delta in b["moves"]:
                    if sku not in pending:
                        row = con.execute(
                            "SELECT qty FROM stock WHERE sku = ?", (sku,)
                        ).fetchone()
                        pending[sku] = row[0] if row else 0
                    pending[sku] += delta
                    if pending[sku] < 0:
                        good = False
                        break

                if good:
                    for sku, qty in pending.items():
                        con.execute(
                            "INSERT OR REPLACE INTO stock (sku, qty) VALUES (?, ?)",
                            (sku, qty),
                        )
                    con.execute("INSERT INTO applied (name) VALUES (?)", (name,))
                    con.execute("COMMIT")
                    status = "applied"
                else:
                    con.execute("ROLLBACK")
            except Exception:
                con.execute("ROLLBACK")
                raise

        print(f"{name} {status}")

    rows = con.execute("SELECT sku, qty FROM stock WHERE qty != 0").fetchall()
    for sku, qty in sorted(rows, key=lambda r: r[0].encode("utf-8")):
        print(f"{sku} {qty}")

    con.close()


if __name__ == "__main__":
    main()

import json
import os
import re
import tempfile
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

COUNTS = os.environ["COUNTS"]
PORT = int(os.environ["PORT"])

NAME_RE = re.compile(r"[a-z0-9-]{1,32}")
lock = threading.Lock()


def load_counts():
    try:
        with open(COUNTS, "r", encoding="utf-8") as f:
            data = json.load(f)
        return {str(k): int(v) for k, v in data.items()}
    except FileNotFoundError:
        return {}


def save_counts(counts):
    directory = os.path.dirname(os.path.abspath(COUNTS))
    fd, tmp_path = tempfile.mkstemp(dir=directory)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        json.dump(counts, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp_path, COUNTS)


counts = load_counts()


class Handler(BaseHTTPRequestHandler):
    server_version = "CounterAPI/1.0"

    def log_message(self, fmt, *args):
        print(f"{self.address_string()} {fmt % args}", flush=True)

    def send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def dispatch(self):
        length = self.headers.get("Content-Length")
        if length:
            try:
                n = int(length)
                if n > 0:
                    self.rfile.read(n)
            except ValueError:
                pass

        method = self.command
        path = self.path

        if method == "POST" and path.startswith("/hit/"):
            name = path[len("/hit/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with lock:
                value = counts.get(name, 0) + 1
                counts[name] = value
                save_counts(counts)
            return self.send_json(200, {"name": name, "count": value})

        if method == "GET" and path.startswith("/count/"):
            name = path[len("/count/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with lock:
                value = counts.get(name, 0)
            return self.send_json(200, {"name": name, "count": value})

        if method == "GET" and path == "/top":
            with lock:
                items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
            return self.send_json(200, [{"name": k, "count": v} for k, v in items])

        return self.send_json(404, {"error": "not found"})

    do_GET = dispatch
    do_POST = dispatch
    do_PUT = dispatch
    do_DELETE = dispatch
    do_PATCH = dispatch
    do_HEAD = dispatch
    do_OPTIONS = dispatch


if __name__ == "__main__":
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    print(f"listening on 127.0.0.1:{PORT}", flush=True)
    server.serve_forever()

