def save_state():
    data = {
        "next_id": STATE["next_id"],
        "todos": [STATE["todos"][k] for k in sorted(STATE["todos"])],
    }
    tmp = STORE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, STORE_PATH)


def not_found():
    return 404, {"error": "not found"}


def parse_json(raw):
    try:
        return True, json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return False, None


def create(raw):
    ok, body = parse_json(raw)
    if not ok or not isinstance(body, dict):
        return 400, {"error": "title required"}
    title = body.get("title")
    if not isinstance(title, str) or not title.strip():
        return 400, {"error": "title required"}
    tid = STATE["next_id"]
    STATE["next_id"] = tid + 1
    todo = {"id": tid, "title": title.strip(), "done": False}
    STATE["todos"][tid] = todo
    save_state()
    return 201, todo


def list_todos(query):
    items = [STATE["todos"][k] for k in sorted(STATE["todos"])]
    done = query.get("done", [None])[-1]
    if done == "true":
        items = [t for t in items if t["done"] is True]
    elif done == "false":
        items = [t for t in items if t["done"] is False]
    return 200, items


def get_todo(tid):
    todo = STATE["todos"].get(tid)
    if todo is None:
        return not_found()
    return 200, todo


def patch_todo(tid, raw):
    todo = STATE["todos"].get(tid)
    if todo is None:
        return not_found()
    bad = (400, {"error": "bad update"})
    ok, body = parse_json(raw)
    if not ok or not isinstance(body, dict):
        return bad
    updates = {}
    if "title" in body:
        t = body["title"]
        if not isinstance(t, str) or not t.strip():
            return bad
        updates["title"] = t.strip()
    if "done" in body:
        d = body["done"]
        if not isinstance(d, bool):
            return bad
        updates["done"] = d
    todo.update(updates)
    save_state()
    return 200, todo


def delete_todo(tid):
    if tid not in STATE["todos"]:
        return not_found()
    del STATE["todos"][tid]
    save_state()
    return 204, None


def route(method, target, raw):
    parts = urlsplit(target)
    path = parts.path
    if path == "/todos":
        if method == "POST":
            return create(raw)
        if method == "GET":
            return list_todos(parse_qs(parts.query))
        return not_found()
    m = ID_RE.fullmatch(path)
    if m:
        tid = int(m.group(1))
        if method == "GET":
            return get_todo(tid)
        if method == "PATCH":
            return patch_todo(tid, raw)
        if method == "DELETE":
            return delete_todo(tid)
    return not_found()


class Handler(BaseHTTPRequestHandler):
    def _dispatch(self):
        length = self.headers.get("Content-Length")
        try:
            n = int(length) if length else 0
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        with LOCK:
            status, body = route(self.command, self.path, raw)

        self.send_response(status)
        if body is None:
            if status != 204:
                self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            data = json.dumps(body).encode("utf-8")
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(data)

    def log_message(self, fmt, *args):
        print("%s - %s" % (self.address_string(), fmt % args), flush=True)


for _name in ("GET", "POST", "PATCH", "DELETE", "PUT", "HEAD", "OPTIONS", "TRACE", "CONNECT"):
    setattr(Handler, "do_" + _name, Handler._dispatch)


def main():
    load_state()
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    print(f"listening on 127.0.0.1:{PORT}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

import json
import os
import re
import sqlite3
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlsplit, parse_qs

SCHEMA = """
CREATE TABLE IF NOT EXISTS notes (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    body  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS tags (
    note_id INTEGER NOT NULL,
    pos     INTEGER NOT NULL,
    tag     TEXT NOT NULL,
    PRIMARY KEY (note_id, tag)
);
CREATE INDEX IF NOT EXISTS tags_by_tag ON tags(tag);
"""

NOT_FOUND = (404, {"error": "not found"})
INVALID_NOTE = (400, {"error": "invalid note"})
MAX_ID = 2 ** 63 - 1


def parse_id(s):
    if not re.fullmatch(r"[1-9][0-9]*", s):
        return None
    n = int(s)
    return n if n <= MAX_ID else None


def parse_note_body(raw):
    try:
        data = json.loads(raw.decode("utf-8"))
    except ValueError:
        return None
    if not isinstance(data, dict):
        return None
    title = data.get("title")
    body = data.get("body")
    tags = data.get("tags", [])
    if not isinstance(title, str) or title == "":
        return None
    if not isinstance(body, str):
        return None
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        return None
    unique = []
    for t in tags:
        t = t.lower()
        if t not in unique:
            unique.append(t)
    return title, body, unique


def create_note(db, title, body, tags):
    with db:
        cur = db.execute("INSERT INTO notes (title, body) VALUES (?, ?)", (title, body))
        nid = cur.lastrowid
        for pos, tag in enumerate(tags):
            db.execute(
                "INSERT INTO tags (note_id, pos, tag) VALUES (?, ?, ?)",
                (nid, pos, tag),
            )
    return nid


def load_note(db, nid):
    row = db.execute(
        "SELECT id, title, body FROM notes WHERE id = ?", (nid,)
    ).fetchone()
    if row is None:
        return None
    tags = [
        r[0]
        for r in db.execute(
            "SELECT tag FROM tags WHERE note_id = ? ORDER BY pos", (nid,)
        )
    ]
    return {"id": row[0], "title": row[1], "body": row[2], "tags": tags}


def delete_note(db, nid):
    with db:
        db.execute("DELETE FROM tags WHERE note_id = ?", (nid,))
        cur = db.execute("DELETE FROM notes WHERE id = ?", (nid,))
        return cur.rowcount > 0


def list_notes(db, query):
    qs = parse_qs(query, keep_blank_values=False)
    clauses, params = [], []
    if "tag" in qs:
        clauses.append("id IN (SELECT note_id FROM tags WHERE tag = ?)")
        params.append(qs["tag"][0].lower())
    if "q" in qs:
        clauses.append("(instr(title, ?) > 0 OR instr(body, ?) > 0)")
        params += [qs["q"][0], qs["q"][0]]
    sql = "SELECT id, title FROM notes"
    if clauses:
        sql += " WHERE " + " AND ".join(clauses)
    sql += " ORDER BY id DESC"
    rows = db.execute(sql, params).fetchall()
    return 200, [{"id": i, "title": t} for i, t in rows]


def route(db, method, target, raw):
    parts = urlsplit(target)
    segs = parts.path.split("/")

    if segs == ["", "notes"]:
        if method == "GET":
            return list_notes(db, parts.query)
        if method == "POST":
            parsed = parse_note_body(raw)
            if parsed is None:
                return INVALID_NOTE
            title, body, tags = parsed
            return 201, {"id": create_note(db, title, body, tags)}
        return NOT_FOUND

    if len(segs) == 3 and segs[0] == "" and segs[1] == "notes":
        nid = parse_id(segs[2])
        if nid is None:
            return NOT_FOUND
        if method == "GET":
            note = load_note(db, nid)
            if note is None:
                return NOT_FOUND
            return 200, note
        if method == "DELETE":
            if not delete_note(db, nid):
                return NOT_FOUND
            return 200, {"deleted": nid}
        return NOT_FOUND

    return NOT_FOUND


class Handler(BaseHTTPRequestHandler):
    server_version = "notes/1.0"

    def _handle(self):
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""

        status, payload = route(self.server.db, self.command, self.path, raw)
        body = json.dumps(payload).encode("utf-8")

        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    do_GET = _handle
    do_POST = _handle
    do_DELETE = _handle
    do_PUT = _handle
    do_PATCH = _handle
    do_OPTIONS = _handle
    do_HEAD = _handle
    do_TRACE = _handle

    def log_message(self, fmt, *args):
        print(f"{self.address_string()} {fmt % args}", flush=True)


def main():
    port = int(os.environ["PORT"])
    db_path = os.environ["DB"]

    db = sqlite3.connect(db_path, check_same_thread=False)
    db.executescript(SCHEMA)

    server = HTTPServer(("127.0.0.1", port), Handler)
    server.db = db

    print(f"listening on 127.0.0.1:{port}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        db.close()


if __name__ == "__main__":
    main()

import json
import os
import urllib.parse
import urllib.request


def get_json(url):
    with urllib.request.urlopen(url, timeout=10) as resp:
        if not (200 <= resp.status < 300):
            raise RuntimeError(f"status {resp.status}")
        return json.loads(resp.read().decode("utf-8"))


def fmt(tenths):
    sign = "-" if tenths < 0 else ""
    a = abs(tenths)
    return f"{sign}{a // 10}.{a % 10}"


def main():
    base = os.environ["API"].rstrip("/")
    stations = get_json(base + "/stations")["stations"]

    rows = []
    for st in stations:
        sid = str(st["id"])
        name = str(st["name"])
        url = f"{base}/stations/{urllib.parse.quote(sid, safe='')}/readings"
        try:
            data = get_json(url)
            temps = [int(r["temp"]) for r in data.get("readings", [])]
        except Exception:
            rows.append((name, None))
            continue
        rows.append((name, temps))

    rows.sort(key=lambda r: r[0].encode("utf-8"))

    for name, temps in rows:
        if temps is None:
            print(f"{name} unavailable")
        elif not temps:
            print(f"{name} no data")
        else:
            total = sum(temps)
            count = len(temps)
            avg = abs(total) // count
            if total < 0:
                avg = -avg
            print(
                f"{name} min={fmt(min(temps))} max={fmt(max(temps))} "
                f"avg={fmt(avg)} n={count}"
            )


if __name__ == "__main__":
    main()
